package desktop

import "fyne.io/fyne/v2"

// App represents a desktop application with extended capabilities beyond the standard fyne.App interface.
// It provides desktop-specific features such as system tray integration.
//
// Since: 2.5
type App interface {
	fyne.App

	// SetSystemTrayMenu sets the menu to be displayed in the system tray.
	// On platforms that support system trays (Windows, macOS, Linux with appropriate desktop environments),
	// this will add an icon to the system tray that opens the specified menu when clicked.
	// Passing nil will remove any existing system tray menu.
	SetSystemTrayMenu(menu *fyne.Menu)
}

